    drugs: ["sotorasib", "adagrasib", "daraxonrasib", "olaparib", "erlotinib", "gemcitabine", "folfirinox", "larotrectinib", "entrectinib", "pembrolizumab"],
    cancers: ["pancreatic"],
    pathways: ["ras-mapk", "pi3k-akt-mtor", "p53-cell-cycle", "tgf-beta", "ddr", "jak-stat", "rtk-activation"],
