    cancers: ["hcc"],
    pathways: ["wnt", "p53-cell-cycle", "pi3k-akt-mtor", "ras-mapk", "keap1-nrf2", "tgf-beta", "vegf-angiogenesis", "pd1-checkpoint", "rtk-activation"],
